'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=null,traces=[],sid=null,filtered=[],pending=null,editing=null,activeTab='evidence',busy=false,selectedTool=null;
const draftKey='cartwheel-hw4-note-draft-v1';
function notice(text){$('#notice').textContent=text;$('#notice').hidden=!text}
function time(value){return value?new Intl.DateTimeFormat('en-US',{timeZone:'UTC',dateStyle:'medium',timeStyle:'medium'}).format(new Date(value))+' UTC':'Time not recorded'}
async function api(path,body){const res=await fetch(path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-Review-Token':state.csrf},body:JSON.stringify(body)});const data=await res.json();if(!res.ok)throw Error(data.error||'Request failed');return data}
function tab(name){activeTab=name;['evidence','spec','notes'].forEach(n=>{$('#'+n).hidden=n!==name;$('#tab-'+n).setAttribute('aria-selected',String(n===name))})}
function currentNotes(){return (state?.annotations||[]).filter(n=>!n.deleted&&traces.some(t=>t.id===n.trace_id))}
function status(){const s=state.status;$('#connection').textContent=s.phase==='live'?`Langfuse connected · ${s.loaded} traces`:s.phase==='loading'?`Loading live traces · ${s.loaded}/${s.total||'…'}`:'Langfuse connection error';if(s.error)notice(s.error);$('#refresh').disabled=s.phase==='loading';$('#spec-version').textContent=`Current specification snapshot ${state.spec_hash.slice(0,10)} · Historical applicability not verified`;}
function initialBatch(){const batch=new URLSearchParams(location.search).get('batch');if(batch==='depth2')return (state.manifest?.samples||[]).filter(x=>x.batch==='depth'&&x.search_round===2).sort((a,b)=>a.review_order-b.review_order).map((x,i)=>({...x,review_order:i+1}));return ['initial','quantity','depth','final_uniform'].includes(batch)?(state.manifest?.samples||[]).filter(x=>x.batch===batch).sort((a,b)=>a.review_order-b.review_order):null}
function buildPicker(){const term=$('#search').value.toLowerCase(),role=$('#role').value;const batch=initialBatch();const rank=s=>Math.min(...(batch||[]).filter(x=>s.trace_ids.includes(x.trace_id)).map(x=>x.review_order));filtered=state.sessions.filter(s=>(!batch||Number.isFinite(rank(s)))&&(!role||s.role===role)&&`${s.scenario_id} ${s.preview}`.toLowerCase().includes(term));if(batch)filtered.sort((a,b)=>rank(a)-rank(b));$('#session').innerHTML=filtered.map(s=>`<option value="${esc(s.id)}">${batch?'Batch '+rank(s)+' / '+batch.length+' · ':''}${esc(s.scenario_id)} · ${s.trace_ids.length} turn${s.trace_ids.length===1?'':'s'} · ${esc(s.preview.slice(0,90))}</option>`).join('');$('#session').value=sid||'';$('#prev').disabled=filtered.findIndex(s=>s.id===sid)<=0;$('#next').disabled=filtered.findIndex(s=>s.id===sid)>=filtered.length-1;}
async function loadState(initial=false){state=await api('/api/state');status();buildPicker();if(initial||(!sid&&state.sessions.length)){const requested=new URLSearchParams(location.search).get('trace');const sample=filtered.find(s=>s.trace_ids.includes(requested||initialBatch()?.[0]?.trace_id||'583fe5f9c948275d0a4cd23f8b13a29d'));await openSession(sample?.id||filtered[0]?.id);restoreDraft()}else{renderNotes();paint();renderProgress();if(!document.activeElement.closest?.('.label-form'))renderTaxonomy()}if(document.activeElement!==$('#spec-search'))renderSpec();renderAiTraceLabels();if(!$('#explore-view').hidden){if(initial||(exploreKind==='tree'&&treeRenderedVersion!==state.ai_assessments?.updated_at))renderExplore()}}
async function openSession(id){if(!id)return;if(pending&&$('#note-text').value.trim()&&sid!==id){backupDraft();notice('Save or cancel your current observation before changing conversations.');buildPicker();return;}sid=id;const data=await api('/api/session?id='+encodeURIComponent(id));traces=data.traces;pending=null;editing=null;selectedTool=null;$('#note-form').hidden=true;buildPicker();renderConversation();renderEvidence();renderNotes();renderAiTraceLabels();paint();renderTaxonomy();renderProgress();$('#spec-search').value='';renderSpec();}
function sourceBlock(tid,key){return traces.find(t=>t.id===tid)?.blocks.find(b=>b.key===key)}
function blockHTML(t,b,tag='p'){return `<${tag} class="annotatable" data-trace="${esc(t.id)}" data-block="${esc(b.key)}">${esc(b.text)}</${tag}>`}
function renderConversation(){const first=traces[0];if(!first){$('#conversation').textContent='No traces in this conversation.';return}const caller=first.caller_context||{name:first.user_name,role:first.role,user_id:first.user_id,store_id:first.store_id};$('#context').innerHTML=`<div class="caller-identity"><span class="muted">Caller</span><strong>${esc(caller.name||'Name not recorded')}</strong><span class="badge">${esc(caller.role||'Role not recorded')}</span><span>User ${esc(caller.user_id||'not recorded')}</span></div><div class="caller-store"><span class="muted">Caller’s store</span><strong>${esc(caller.store_name||(caller.store_id!=null?'Store '+caller.store_id:caller.role==='shopper'?'Not applicable — shopper':caller.role==='support'?'Not applicable — support':'Not recorded'))}</strong>${caller.store_name?`<span>Store ${esc(caller.store_id)}</span>`:''}</div><div><span>${esc(time(first.timestamp))}</span><div class="muted">${caller.supplemented?'Identity supplemented from saved scenario context; matched to trace caller.':'Identity from recorded trace metadata.'}</div></div>`;
$('#conversation').innerHTML=`<div class="trace-head"><h2>Conversation</h2><span class="muted">${traces.length} distinct trace${traces.length===1?'':'s'} in this session</span></div><p class="muted">Highlight a phrase to add an observation. Open a tool to inspect its recorded arguments and result.</p>`+traces.map((t,i)=>`<section class="trace" data-trace-id="${esc(t.id)}"><div class="trace-head"><div><h3>Turn ${i+1} · ${esc(t.scenario_id)}</h3><div class="muted">${esc(time(t.timestamp))}</div></div><a href="${esc(t.url)}" target="_blank" rel="noopener">Langfuse ↗</a></div>${t.blocks.map(b=>{if(b.role==='tool_result')return '';if(b.role==='tool')return `<div class="activity"><button data-tool="${esc(b.tool_id)}" data-tid="${esc(t.id)}"><code>${esc(b.name)}</code> · View arguments & result →</button></div>`;return `<article class="message ${esc(b.role)}"><div class="speaker">${b.role==='user'?'User · '+esc(t.role):'Assistant'}</div>${blockHTML(t,b)}</article>`}).join('')}<div class="actions"><button data-clean="${esc(t.id)}">Record “no failure observed”</button><span class="muted">${state.annotations.some(n=>n.trace_id===t.id&&!n.deleted)?'Has human annotation':'Not yet annotated'}</span></div><details class="raw"><summary>Full recorded trace, system prompt & technical details</summary><pre>${esc(JSON.stringify(t.raw,null,2))}</pre></details></section>`).join('');}

function structuredResult(tool){
 const o=tool.output;
 if(!o||typeof o!=='object')return '<p>No structured result recorded. Inspect the original result below.</p>';
 const value=v=>v==null?'Not recorded':typeof v==='boolean'?(v?'Yes':'No'):typeof v==='object'?JSON.stringify(v):String(v);
 const table=(obj,fields)=>'<table class="facts">'+fields.map(([key,label])=>`<tr><th>${esc(label)}</th><td>${esc(value(obj[key]))}</td></tr>`).join('')+'</table>';
 const section=(title,body)=>`<section class="evidence-card"><h3>${esc(title)}</h3>${body}</section>`;
 const prose=text=>text==null?'':`<p class="evidence-prose">${esc(text)}</p>`;
 const policies=items=>section('Retrieved policies',items.length?items.map(p=>`<details class="policy-card"><summary>${esc(p.title||p.policy_id||'Untitled policy')}</summary>${p.snippet?'<p class="muted">Search excerpt · may be incomplete</p>':''}${prose(p.body??p.snippet)}${table(p,[['policy_id','Policy ID'],...(p.audience!==undefined?[['audience','Audience']]:[]),...(p.score!==undefined?[['score','Retrieval score (not confidence)']]:[])])}</details>`).join(''):'<p>No policies returned.</p>');
 const orderFields=[['order_id','Order'],['product_name','Product'],['store_name','Store'],['quantity','Quantity'],['total_usd','Amount (USD)'],['status','Status'],['ordered_at','Ordered'],['shipped_at','Shipped'],['delivered_at','Delivered']];
 let html=section('Tool outcome',o.ok===false?table(o,[['error','Error'],['reason','Explanation'],['denial_reason','Scope restriction']]):prose(o.ok===true?'Tool completed successfully. This does not by itself mean an action was approved.':'Success status not recorded.'));
 if(o.ok===false)return html;
 if(tool.name==='get_order'&&o.order)html+=section('Recorded order',table(o.order,[...orderFields,['refund_eligible','Stored refund eligibility']]));
 else if(['get_applicable_policies','check_refund_eligibility'].includes(tool.name)){
  html+=section('Recorded order context',table(o,orderFields));
  if(tool.name==='check_refund_eligibility')html+=section('Eligibility assessment',table(o,[['eligible','Eligible under recorded rules'],['reason','Reason'],['reason_code','Reason code'],['stored_refund_eligible','Stored eligibility flag'],['scope','Assessment scope']]));
  html+=section('Return timing',table(o,[['evaluated_as_of','Evaluated as of'],['return_window_days','Return window (days)'],['store_override_days','Store override (days)'],['days_since_delivery','Days since delivery'],...(tool.name==='get_applicable_policies'?[['days_remaining','Days remaining (negative = past cutoff)'],['eligibility_cutoff_date','Calculated eligibility cutoff']]:[])] )+prose(o.date_warning));
  if(o.deadline_semantics)html+=section('What the cutoff means',table(o.deadline_semantics,[['eligibility_day_boundary','Boundary'],['required_event','Required event'],['time_of_day','Time of day'],['timezone','Time zone']])+prose(o.deadline_semantics.note)+prose(o.deadline_semantics.boundary_source));
  if(tool.name==='get_applicable_policies')html+=section('Conditions and fees',table(o,[['condition_rule','Condition rule'],['specific_condition_requirements','Specific requirements'],['store_has_policy','Store policy recorded'],['window_source','Window source']])+prose(o.condition_note)+(o.restocking_fee?table(o.restocking_fee,[['store_opted_in','Store opted into fee'],['max_percent','Maximum fee (%)'],['applies_to','Fee application']]):'')+(o.listing_description?`<details><summary>Recorded listing description</summary>${prose(o.listing_description)}</details>`:''));
  if(Array.isArray(o.policy_references))html+=policies(o.policy_references);
 }else if(tool.name==='search_help_center')html+=policies(o.results||[]);
 else if(tool.name==='get_policy')html+=policies([o]);
 else if(tool.name==='issue_refund')html+=section('Refund result',table(o,[['order_id','Order'],['amount_usd','Refund amount (USD)'],['status','Recorded refund status'],['refund_id','Refund reference']])+prose(o.note));
 else if(tool.name==='search_products')html+=section('Products',prose(`${o.count??(o.products||[]).length} results returned`)+(o.products||[]).map(p=>`<details class="policy-card" open><summary>${esc(p.title||'Unnamed product')}</summary>${table(p,[['price_usd','Price (USD)'],['product_id','Product ID'],['store_id','Store ID']])}</details>`).join(''));
 else html+=section('Recorded fields',table(o,Object.keys(o).filter(k=>k!=='ok').map(k=>[k,k.replaceAll('_',' ')])));
 return html;
}

function renderEvidence(){const pairs=traces.flatMap(t=>t.tools.map(tool=>({t,tool})));const choice=selectedTool?pairs.find(p=>p.tool.id===selectedTool):pairs[0];if(!choice){$('#evidence').innerHTML='<h2>Tool evidence</h2><p>No tool calls were recorded in this session.</p>';return}const {t,tool}=choice;selectedTool=tool.id;const order=tool.output?.order;const policyTools=pairs.filter(p=>/policy|policies|help_center/.test(p.tool.name));$('#evidence').innerHTML=`<h2>Recorded evidence</h2><label for="tool-picker">Tool call</label><select id="tool-picker" style="width:100%">${pairs.map(p=>`<option value="${esc(p.tool.id)}" ${p.tool.id===tool.id?'selected':''}>${esc(p.tool.name)} · ${esc(p.t.scenario_id)}</option>`).join('')}</select><p class="muted">${esc(time(tool.timestamp))} · Historical tool result</p>${structuredResult(tool)}<h3>Arguments</h3>${t.blocks.filter(b=>b.key===tool.id+':call').map(b=>blockHTML(t,b,'pre')).join('')}<details><summary>Original result · highlight text here to annotate</summary>${t.blocks.filter(b=>b.key===tool.id+':result').map(b=>blockHTML(t,b,'pre')).join('')||'<p>No result recorded.</p>'}</details>${tool.status_message?`<p>${esc(tool.status_message)}</p>`:''}<details><summary>Policy retrieval in this session (${policyTools.length} calls)</summary>${policyTools.map(p=>`<p><button data-tool="${esc(p.tool.id)}" data-tid="${esc(p.t.id)}">${esc(p.tool.name)} · ${esc(p.t.scenario_id)}</button></p>`).join('')||'<p>None recorded.</p>'}<p class="muted">Retrieved documents are evidence available to the agent; this does not mean every document was cited in the reply.</p></details>`;$('#tool-picker').onchange=e=>{selectedTool=e.target.value;renderEvidence();paint()};}
// Select source excerpts without using review labels or treating retrieval as a verdict.
function relevantSpec(spec, conversation){
 const user=conversation.flatMap(t=>t.blocks.filter(b=>b.role==='user').map(b=>b.text)).join(' ').toLowerCase();
 const tools=new Set(conversation.flatMap(t=>t.tools.map(x=>x.name)));
 const outputs=conversation.flatMap(t=>t.tools.map(x=>JSON.stringify(x.output))).join(' ').toLowerCase();
 const has=(re)=>re.test(user), called=(re)=>[...tools].some(n=>re.test(n));
 const refund=has(/refund|money back|reimburse|return/)||called(/refund|applicable_policies/);
 const order=has(/order|shipment|shipping|delivery|delivered|parcel|package|tracking/)||called(/order/);
 const policy=refund||has(/polic|eligible|eligibility|allowed|warranty|how long|how many days/)||called(/policy|policies|help_center/);
 const eligibility=refund&&(order||has(/return|eligible|eligibility|can i|can you|please|process|issue|approve|denied|denial|refused/));
 const action=has(/cancel|change|update|escalat|(?:process|issue|approve|request|get|want|need).*refund/)||called(/refund|cancel|escalate/);
 const scope=has(/legal|lawyer|credit card|payment card|card number|password|other compan|weather|politic/);
 const ids=new Map();
 const add=(names,reason)=>names.split(' ').forEach(id=>ids.set(id,reason));
 add('RESP-3 RESP-5 RESP-7 RESP-12','Applies across conversations: accuracy, tone, relevance, and caller role.');
 if(conversation.some(t=>t.role==='shopper'))add('RESP-10','Shopper-facing wording and identifiers.');
 if(policy)add('RESP-1 RESP-11','Policy guidance: claims need specific supporting sources and case facts.');
 if(order||action)add('AUTH-1 RESP-4','Order access or an action: check caller permissions and information disclosure.');
 if(action)add('RESP-2','An action is requested or recorded: success must be supported by the tool result.');
 if(order&&has(/status|where|arriv|track|shipped|deliver|when/))add('RESP-6','The request concerns order status or delivery.');
 if(order&&has(/detail|information|tell me about|show|summary|overview/))add('RESP-8','The request may call for broader order details.');
 if(eligibility)add('ESC-1 ESC-4 RESP-9 RESP-11','Refund or return context: check eligibility, supporting policies, and approval authority.');
 if(has(/(?:change|update|edit|replace|delete|close|reset).*(?:account|address|email|phone|name|password)|(?:account|address|email|phone|name|password).*(?:change|update|edit|replace|delete|close|reset)/))add('ESC-2','The request mentions account information or a possible account change.');
 if(has(/disput|chargeback|human|supervisor|complaint|contradict|uncertain/)||called(/escalate/)||/"ok":false/.test(outputs))add('ESC-3 ESC-4 RESP-4','Escalation, uncertainty, or a failed tool result may require human help.');
 if(scope)add('SCOPE-1 SCOPE-2','The request may involve a scope boundary.');
 const excerpts=[];
 const sections=spec.split(/(?=^## )/m);
 for(const section of sections){
  const heading=(section.match(/^## (.+)/m)||[])[1]||'Specification';
  // A numbered requirement extends through its continuation paragraphs, lists and tables.
  const marker=/^(?:- )?\*\*((?:PURPOSE|SCOPE|AUTH|ESC|RESP)-\d+)\.\*\*/gm;
  const matches=[...section.matchAll(marker)];
  matches.forEach((m,i)=>{if(ids.has(m[1]))excerpts.push({id:m[1],heading,reason:ids.get(m[1]),text:section.slice(m.index,matches[i+1]?.index??section.length).trim()});});
  if(heading==='5. Escalation policy'&&eligibility){const text=section.split('The following cases always go to a human:')[0].replace(/^## .*\n/,'').trim();if(text)excerpts.push({id:'Return-policy resolution',heading,reason:'Return/refund context: applicable policies, dates, and unresolved conditions.',text});}
  if(heading==='4. Tools'){
   const lines=section.split('\n');
   if(tools.size)excerpts.push({id:'Tool result handling',heading,reason:'Tools were called; interpret their results and permission denials.',text:section.split('| ID |')[0].replace(/^## .*\n/,'').trim()});
   for(const name of tools){const rows=lines.filter(l=>l.startsWith('|')&&l.includes('`'+name+'`'));if(rows.length)excerpts.push({id:name,heading,reason:'This tool appears in the recorded conversation.',text:rows.map(row=>{const header=row.includes('| TOOL-')?'| ID | Tool | Inputs | Side effects | Risk |':'| Tool | On success | On failure |';return header+'\n'+row}).join('\n\n')});}
  }
 }
 return excerpts.sort((a,b)=>Number(a.reason.startsWith('Applies across'))-Number(b.reason.startsWith('Applies across')));
}
function renderSpec(){
 if(!state)return;
 const q=$('#spec-search').value.trim().toLowerCase(),full=$('#spec-full').checked;
 const excerpts=relevantSpec(state.spec,traces);
 $('#spec-summary').textContent=full?'Full specification reference.':`${excerpts.length} suggested excerpts for this conversation. Selection is based on requests, role, and tools; it may miss relevant rules and is not a judgment of the response.`;
 const items=full?[{id:'Full specification',text:state.spec,reason:''}]:excerpts;
 $('#spec-results').innerHTML=items.filter(p=>!q||`${p.id} ${p.text} ${p.reason}`.toLowerCase().includes(q)).map(p=>`<div class="rule"><h3>${esc(p.id)}</h3>${p.reason?`<p class="muted">${esc(p.reason)}</p>`:''}<pre style="white-space:pre-wrap;font:inherit">${esc(p.text)}</pre></div>`).join('')||'<p>No matching excerpts. Clear the search or show the full specification to check other requirements.</p>';
}
function capture(){const selection=window.getSelection();if(!selection||selection.isCollapsed||!selection.rangeCount)return;const r=selection.getRangeAt(0);const el=r.startContainer.parentElement?.closest('.annotatable');if(!el||!el.contains(r.endContainer)||!selection.toString().trim())return;if(pending&&$('#note-text').value.trim()){notice('Save or cancel your current observation before selecting another passage.');return}const prefix=r.cloneRange();prefix.selectNodeContents(el);prefix.setEnd(r.startContainer,r.startOffset);const start=prefix.toString().length;pending={trace_id:el.dataset.trace,block_key:el.dataset.block,start,end:start+r.toString().length,quote:r.toString(),kind:'observation'};editing=null;selection.removeAllRanges();$('#note-text').value='';paint();showEditor();}
function showEditor(){tab('notes');$('#note-form').hidden=false;$('#quote').textContent=pending.quote||'Whole trace: no failure observed';$('#note-anchor').textContent=`${traces.find(t=>t.id===pending.trace_id)?.scenario_id||pending.trace_id} · ${sourceBlock(pending.trace_id,pending.block_key)?.role||'Trace review'}`;$('#draft-state').textContent='Not saved yet';$('#note-text').focus();}
function resetNote(){pending=null;editing=null;$('#note-form').hidden=true;$('#note-text').value='';localStorage.removeItem(draftKey);paint()}
function backupDraft(){if(pending)localStorage.setItem(draftKey,JSON.stringify({sid,pending,editing,note:$('#note-text').value}));$('#draft-state').textContent='Draft backed up in this browser · Not yet saved to Langfuse';}
function restoreDraft(){try{const draft=JSON.parse(localStorage.getItem(draftKey)||'null');if(draft&&draft.sid===sid){pending=draft.pending;editing=draft.editing;$('#note-text').value=draft.note;showEditor();paint()}}catch{}}
function paint(){if(window.getSelection()?.toString())return;document.querySelectorAll('mark[data-note]').forEach(m=>m.replaceWith(...m.childNodes));document.querySelectorAll('.annotatable').forEach(el=>{el.normalize();const ranges=currentNotes().filter(n=>n.trace_id===el.dataset.trace&&n.block_key===el.dataset.block);if(pending&&pending.trace_id===el.dataset.trace&&pending.block_key===el.dataset.block)ranges.push({...pending,id:'pending'});const text=el.textContent;const cuts=new Set([0,text.length]);ranges.forEach(n=>{if(n.start>=0&&n.end<=text.length){cuts.add(n.start);cuts.add(n.end)}});const bounds=[...cuts].sort((a,b)=>a-b);el.replaceChildren();for(let i=0;i<bounds.length-1;i++){const a=bounds[i],b=bounds[i+1],hits=ranges.filter(n=>n.start<b&&n.end>a),part=text.slice(a,b);if(!hits.length)el.append(document.createTextNode(part));else{const m=document.createElement('mark');m.textContent=part;m.dataset.note=hits.map(n=>n.id).join(' ');if(hits.some(n=>n.id==='pending'))m.className='pending';el.append(m)}}});}
function renderNotes(){if(!state)return;const notes=currentNotes();$('#note-count').textContent=notes.length||'';$('#note-list').innerHTML=notes.map(n=>`<article class="note-card" data-note-card="${esc(n.id)}"><div class="muted">${esc(traces.find(t=>t.id===n.trace_id)?.scenario_id)} · ${n.sync==='synced'?'Saved locally & sent to Langfuse':'Saved locally · Sync pending'}</div>${n.quote?`<blockquote>${esc(n.quote)}</blockquote>`:''}<p>${esc(n.note||n.text)}</p><div class="actions"><button data-edit="${esc(n.id)}">Edit</button><button data-delete="${esc(n.id)}">Delete</button></div></article>`).join('')||'<p class="muted">No observations saved for this conversation.</p>';const suggestions=state.suggestions.filter(s=>traces.some(t=>t.id===s.trace_id)&&!['accepted','rejected'].includes(s.status));$('#suggestions').innerHTML=suggestions.map(s=>`<div class="suggestion"><h3>AI suggestion · Not a human judgment</h3><blockquote>${esc(s.quote||s.text)}</blockquote><p>${esc(s.note||s.reason||s.mode||'')}</p><div class="actions"><button data-accept="${esc(s.id)}">Review & accept</button><button data-reject="${esc(s.id)}">Reject</button></div></div>`).join('');}
function renderProgress(){if(!state)return;const ids=new Set(state.sessions.flatMap(s=>s.trace_ids)),notes=state.annotations.filter(n=>ids.has(n.trace_id)&&!n.deleted),reviewed=new Set(notes.map(n=>n.trace_id));const finals=state.modes.filter(m=>m.status==='final'),labels=state.labels.filter(l=>ids.has(l.trace_id)&&finals.some(m=>m.name===l.mode)),pendingWrites=[...state.annotations,...state.labels].filter(r=>r.sync==='pending');$('#progress-content').innerHTML=`<p><strong>${reviewed.size} distinct traces annotated</strong> out of ${ids.size} available in this HW3 cohort.</p><p>${state.sessions.length} conversations · ${notes.length} active observations · ${pendingWrites.length} pending Langfuse writes</p><p>${finals.length} final modes · ${labels.length} saved trace–mode judgments</p><p>${state.modes.filter(m=>m.status==='accepted').length} accepted definitions · ${state.ai_assessments?.assessed_traces||0} AI-assessed traces · ${aiLabels().length} separate AI trace–category assessments. AI assessments do not increase the human review count.</p><h2>Assignment sampling</h2>${state.manifest?`<pre>${esc(JSON.stringify(state.manifest,null,2))}</pre>`:'<p>The required four-batch sample has not been selected yet. Browsing this cohort does not assign traces to a homework batch.</p><p class="muted">15 uniform + 15 cluster representatives · 30 across a chosen product dimension · 25 depth-search cases · 15 final uniform checks, without duplicate trace IDs.</p>'}<h2>Sample fractions</h2>${finals.map(m=>{const ls=labels.filter(l=>l.mode===m.name&&reviewed.has(l.trace_id));return `<p>${esc(m.name)}: ${ls.filter(l=>l.label===1).length}/${ls.length} labeled reviewed traces; ${reviewed.size-ls.length} judgments incomplete.</p>`}).join('')||'<p>No final taxonomy yet. Fractions will appear after human labeling.</p>'}`;}
function renderTaxonomy(){if(!state)return;$('#mode-list').innerHTML=state.modes.map(m=>`<article class="mode"><h2>${esc(m.name)}</h2><span class="badge">${esc(m.status||'candidate')}</span><p>${esc(m.definition||m.description||'')}</p><details><summary>Evidence, boundaries & requirement source</summary><pre>${esc(JSON.stringify(m,null,2))}</pre></details></article>`).join('')||'<p>No modes have been defined. We will build the taxonomy from your observations after review.</p>';const finals=state.modes.filter(m=>m.status==='final');$('#labeling').innerHTML=finals.length?'<h2>Label this conversation</h2>'+traces.map(t=>`<h3>${esc(t.scenario_id)}</h3>`+finals.map(m=>{const l=state.labels.find(l=>l.trace_id===t.id&&l.mode===m.name);return `<form class="label-form" data-tid="${esc(t.id)}" data-mode="${esc(m.name)}" data-revision="${l?.revision||0}"><label>${esc(m.name)} <select name="label" required><option value="">Not judged</option><option value="1" ${l?.label===1?'selected':''}>Present (Fail)</option><option value="0" ${l?.label===0?'selected':''}>Absent (Pass)</option></select></label><textarea name="note" required placeholder="Evidence supporting your judgment">${esc(l?.note||'')}</textarea><button>Save judgment</button><span class="muted"> ${l?esc(l.sync):'Not labeled'}</span></form>`}).join('')).join(''):'';$('#labeling').innerHTML+='<h2>AI assessments for this conversation</h2><p>These do not replace human judgments.</p>'+traces.map(t=>`<h3>${esc(t.scenario_id)}</h3>${aiLabels().filter(l=>l.trace_id===t.id).map(assessmentCard).join('')||'<p>Not assessed yet.</p>'}`).join('');}

async function saveForm(e){e.preventDefault();if(!pending||busy)return;busy=true;const button=e.submitter||$('#note-form button[type="submit"]');button.disabled=true;try{backupDraft();const body={...pending,note:$('#note-text').value};if(editing){body.id=editing.id;body.revision=editing.revision}const result=pending.suggestion_id?await api('/api/suggestion',{id:pending.suggestion_id,decision:'accepted',annotation:body}):await api('/api/note',body);resetNote();await loadState();renderConversation();paint();notice(result.sync==='pending'?'Saved locally. Langfuse sync is pending; use Retry pending writes in Progress.':'Observation saved.');}catch(err){notice(err.message)}finally{busy=false;button.disabled=false}}
document.addEventListener('pointerup',e=>{if(e.target.closest('.annotatable'))setTimeout(capture,0)});document.addEventListener('keyup',e=>{if(e.key==='Shift')capture()});
document.addEventListener('mouseover',e=>{const mark=e.target.closest('mark[data-note]'),card=e.target.closest('[data-note-card]');if(mark||card){const id=card?.dataset.noteCard||mark.dataset.note.split(' ')[0];document.querySelectorAll('mark[data-note], [data-note-card]').forEach(el=>el.classList.toggle('active',(el.dataset.note||el.dataset.noteCard).split(' ').includes(id)))}});
document.addEventListener('mouseout',e=>{if(e.target.closest('mark,[data-note-card]'))document.querySelectorAll('.active').forEach(el=>el.classList.remove('active'))});
document.addEventListener('click',async e=>{const b=e.target.closest('button');try{if(b?.dataset.tab)tab(b.dataset.tab);if(b?.dataset.view){const view=b.dataset.view;$('#workspace').hidden=view!=='review';$('#explore-view').hidden=view!=='explore';if(view==='explore')renderExplore();$('#taxonomy-view').hidden=view!=='taxonomy';$('#progress-view').hidden=view!=='progress';document.querySelectorAll('[data-view]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderTaxonomy();renderProgress()}if(b?.dataset.tool){selectedTool=b.dataset.tool;tab('evidence');renderEvidence();paint()}const mark=e.target.closest('mark[data-note]');const editId=b?.dataset.edit||(mark&&mark.dataset.note.split(' ').find(id=>id!=='pending'));if(editId){const n=state.annotations.find(n=>n.id===editId);if(n){pending={...n};editing=n;$('#note-text').value=n.note;paint();showEditor()}}if(b?.dataset.delete){const n=state.annotations.find(n=>n.id===b.dataset.delete);await api('/api/note',{...n,deleted:true});if(editing?.id===n.id)resetNote();await loadState()}if(b?.dataset.clean){if(pending&&$('#note-text').value.trim()){notice('Save or cancel the current observation first.');return}await api('/api/note',{trace_id:b.dataset.clean,kind:'no_failure_observed',note:'no failure observed'});await loadState();renderConversation()}if(b?.dataset.reject){await api('/api/suggestion',{id:b.dataset.reject,decision:'rejected',reason:'Rejected by human reviewer'});await loadState()}if(b?.dataset.accept){const s=state.suggestions.find(s=>s.id===b.dataset.accept);const t=traces.find(t=>t.id===s.trace_id),quote=s.quote||s.text;const block=t?.blocks.find(b=>b.key===s.block_key)||t?.blocks.find(b=>quote&&b.text.includes(quote));if(!block){notice('Select the supporting passage yourself; this suggestion does not have a matching text anchor.');return}const start=block.text.indexOf(quote);if(start<0)throw Error('Suggestion quote does not match.');pending={trace_id:t.id,block_key:block.key,start,end:start+quote.length,quote,kind:'observation',suggestion_id:s.id};editing=null;$('#note-text').value=s.note||s.reason||'';paint();showEditor()}}catch(err){notice(err.message)}});
$('#note-form').onsubmit=saveForm;$('#cancel-note').onclick=resetNote;$('#note-text').oninput=backupDraft;$('#note-text').onkeydown=e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();$('#note-form').requestSubmit()}if(e.key==='Escape')resetNote()};$('#spec-search').oninput=renderSpec;$('#spec-full').onchange=renderSpec;$('#search').oninput=buildPicker;$('#role').onchange=buildPicker;$('#session').onchange=e=>openSession(e.target.value).catch(e=>notice(e.message));$('#prev').onclick=()=>openSession(filtered[filtered.findIndex(s=>s.id===sid)-1]?.id);$('#next').onclick=()=>openSession(filtered[filtered.findIndex(s=>s.id===sid)+1]?.id);$('#refresh').onclick=async()=>{try{await api('/api/refresh',{});await loadState()}catch(e){notice(e.message)}};$('#retry').onclick=async()=>{try{await api('/api/retry',{});await loadState();notice('Retry complete. Check Progress for any remaining pending writes.')}catch(e){notice(e.message)}};
document.addEventListener('submit',async e=>{if(!e.target.matches('.label-form'))return;e.preventDefault();const f=e.target,data=new FormData(f);try{await api('/api/label',{trace_id:f.dataset.tid,mode:f.dataset.mode,revision:Number(f.dataset.revision),label:Number(data.get('label')),note:data.get('note')});await loadState()}catch(err){notice(err.message)}});
window.addEventListener('beforeunload',e=>{if(pending&&$('#note-text').value.trim()){backupDraft();e.preventDefault();e.returnValue=''}});
