let exploreKind=new URLSearchParams(location.search).get('map')==='taxonomy'?'tree':'clusters';
const clusterColors=['#2563eb','#b45309','#7c3aed','#07836a','#c02664','#53731b','#b33b28','#52677d'];
const modeTitle=name=>({unverified_user_claim_as_fact:'Unverified user claim as fact',insufficient_directness:'Insufficient directness',technical_or_formal_wording:'Technical or formal wording',unnecessary_detail_or_repetition:'Unnecessary detail & repetition',unnecessary_internal_operation_disclosure:'Unnecessary internal-operation disclosure',unsupported_policy_claim:'Policy claims without retrieval support',unsupported_past_decision_explanation:'Unsupported explanation of a past decision',unclear_or_unsupported_return_deadline:'Unclear or unsupported return deadline'})[name]||name.replaceAll('_',' ');
let treeScope='all',treeResult='present',activeTreeMode=null,activeSubtype=null,treeRenderedVersion=null;
function aiLabels(){return state?.ai_assessments?.labels||[];}
function humanReviewed(){return new Set((state?.annotations||[]).filter(n=>!n.deleted).map(n=>n.trace_id));}
function scopedLabels(){const reviewed=humanReviewed();return aiLabels().filter(l=>treeScope==='all'||(treeScope==='reviewed'?reviewed.has(l.trace_id):!reviewed.has(l.trace_id)));}
function noteGroups(){return (state?.modes||[]).map(m=>{const labels=scopedLabels().filter(l=>l.mode===m.name);return {name:m.name,mode:m,labels,notes:labels.filter(l=>l.label===1)};});}
function assessmentCard(l){return `<article class="ai-assessment"><strong>${esc(modeTitle(l.mode))}</strong> <span class="badge">AI · ${l.label===1?'Present':l.label===0?'Absent':'Uncertain'}</span><p>${esc(l.reason)}</p>${l.quote?`<blockquote>${esc(l.quote)}</blockquote>`:''}${l.subtypes?.length?`<p class="muted">Subtype: ${l.subtypes.map(x=>esc(modeTitle(x))).join(', ')}</p>`:''}${l.assessment_basis==='accepted_taxonomy_refinement'?'<p class="muted">Uses your accepted customer-purpose refinement; not a verdict under the old specification alone.</p>':''}${l.review_history?.length?`<details><summary>AI spot-check correction · original model judgment</summary>${l.review_history.map(h=>`<p>${esc(h.reviewer)} revised the automated assessment.</p><p>Original: ${h.previous_assessment.label===1?'Present':h.previous_assessment.label===0?'Absent':'Uncertain'} — ${esc(h.previous_assessment.reason)}</p>`).join('')}</details>`:''}</article>`;}
function renderAiTraceLabels(){const el=$('#ai-trace-labels');if(!el)return;const labels=aiLabels().filter(l=>traces.some(t=>t.id===l.trace_id));el.innerHTML='<h2>AI taxonomy assessments</h2><p class="muted">Automated assessments, not human-confirmed labels. Original observations above are unchanged.</p>'+ (labels.length?traces.map(t=>`<h3>${esc(t.scenario_id)}</h3>${labels.filter(l=>l.trace_id===t.id).map(assessmentCard).join('')}`).join(''):'<p>Not assessed yet.</p>');}
function renderExplore(){
 if(!state){$('#explore-chart').textContent='Loading review state…';return;}
 if(exploreKind==='tree'){renderTree();return;}
 const points=clusterData.points,selected=new Set((state.manifest?.samples||[]).map(s=>s.trace_id)),reviewed=new Set(state.annotations.filter(n=>!n.deleted).map(n=>n.trace_id));
 const xs=points.map(p=>p.x),ys=points.map(p=>p.y),minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);
 const dots=points.map((p,i)=>{const x=45+(p.x-minX)/(maxX-minX||1)*810,y=35+(p.y-minY)/(maxY-minY||1)*390;return `<g><circle tabindex="0" role="button" aria-label="${esc(p.scenario)} · ${esc(p.role)} · cluster ${p.cluster+1}" data-point="${i}" cx="${x}" cy="${y}" r="${selected.has(p.id)?7:4}" fill="${clusterColors[p.cluster]}" stroke="${selected.has(p.id)?'#142238':'white'}" stroke-width="${selected.has(p.id)?2:1}"><title>${esc(p.scenario)} · ${esc(p.role)} · ${reviewed.has(p.id)?'Annotated':'Not annotated'} — ${esc(p.preview)}</title></circle>${reviewed.has(p.id)?`<circle cx="${x}" cy="${y}" r="2" fill="white" pointer-events="none"/>`:''}</g>`}).join('');
 $('#explore-chart').innerHTML=`<h2>Structural clusters · ${points.length} traces</h2><p>Same eight clusters used for the initial representative sample. PCA projects 18 standardized features into two dimensions (${clusterData.explained}% of variance retained). Nearby dots have similar recorded structure, roles, and tool usage—not necessarily similar failures.</p><p>Large outlined dot = selected for review · White center = has a saved annotation. Hover or select a dot. Overlapping points can be selected individually in the list below.</p><div class="map-legend">${clusterColors.map((c,i)=>`<span><i class="map-dot" style="background:${c}"></i> Cluster ${i+1}</span>`).join('')}</div><svg viewBox="0 0 900 470" aria-label="Interactive trace cluster map">${dots}<text x="400" y="460">Principal component 1</text><text x="8" y="18">PC 2</text></svg><label>Find a trace in the map <select id="map-trace"><option value="">Select scenario…</option>${points.map((p,i)=>`<option value="${i}">${esc(p.scenario)} · ${esc(p.role)} · cluster ${p.cluster+1}</option>`).join('')}</select></label>`;
 $('#explore-details').innerHTML='<p>Select a trace to see its request, review status, and saved notes.</p>';
 $('#map-trace').onchange=e=>{if(e.target.value!=='')showMapPoint(Number(e.target.value));};
}
function showMapPoint(i){const p=clusterData.points[i],notes=state.annotations.filter(n=>!n.deleted&&n.trace_id===p.id),sample=state.manifest?.samples.find(s=>s.trace_id===p.id);$('#explore-details').innerHTML=`<h2>${esc(p.scenario)}</h2><p>${esc(p.role)} · Cluster ${p.cluster+1} · ${sample?'Selected: '+esc(sample.batch):'Not selected for a homework batch'} · ${notes.length} saved notes</p><p>${esc(p.preview)}</p><a href="/?trace=${encodeURIComponent(p.id)}" target="_blank" rel="noopener">Open conversation for review ↗</a>${notes.map(n=>`<p>${esc(n.note||n.text)}</p>`).join('')}`;}
function treeRects(items,x,y,w,h){if(items.length===1)return [{g:items[0],x,y,w,h}];const total=items.reduce((n,g)=>n+g.notes.length,0);let k=1,part=items[0].notes.length;while(k<items.length-1&&part<total/2){part+=items[k++].notes.length;}const f=part/total;return w>=h?[...treeRects(items.slice(0,k),x,y,w*f,h),...treeRects(items.slice(k),x+w*f,y,w*(1-f),h)]:[...treeRects(items.slice(0,k),x,y,w,h*f),...treeRects(items.slice(k),x,y+h*f,w,h*(1-f))];}
function renderTree(){
 treeRenderedVersion=state.ai_assessments?.updated_at;
 const groups=noteGroups(), data=state.ai_assessments||{}, reviewed=humanReviewed();
 const available=state.sessions.flatMap(s=>s.trace_ids).filter(id=>treeScope==='all'||(treeScope==='reviewed'?reviewed.has(id):!reviewed.has(id))).length;
 $('#explore-chart').innerHTML=`<h2>Accepted taxonomy · ${groups.length} categories</h2><p>${data.assessed_traces||0}/${data.total_traces||state.sessions.flatMap(s=>s.trace_ids).length} traces assessed by AI (${esc(data.model||'pending')}). Human observations remain separate. Counts are automated findings, not validated failure rates.</p><div class="actions"><label>Trace scope <select id="tree-scope"><option value="all">All traces</option><option value="reviewed">With human observations</option><option value="unreviewed">Without human observations</option></select></label><label>Show assessments <select id="tree-result"><option value="present">Present</option><option value="absent">Absent</option><option value="uncertain">Uncertain</option><option value="all">All results</option></select></label></div><p>${available} traces in this scope. Tiles scale roughly with AI-present counts, with a minimum size for readability; narrow screens use equal tiles. One trace can appear in several categories.</p><div class="tree-box">${treeRects(groups.map(g=>({...g,notes:g.notes.length>=8?g.notes:Array(8).fill({})})),0,0,100,100).map((r,i)=>{const g=groups.find(g=>g.name===r.g.name);return `<button class="tree-tile" data-group="${esc(g.name)}" style="left:${r.x}%;top:${r.y}%;width:${r.w}%;height:${r.h}%;background:${['#dce9ff','#e8dff8','#d9eee8','#f9e7ca','#f7dce6','#e4ebcf'][i%6]}"><strong>${esc(modeTitle(g.name))}</strong>${g.notes.length} AI-present · ${g.labels.filter(l=>l.label===null).length} uncertain<br>${g.mode.originating_annotations?.length||0} originating observations</button>`;}).join('')}</div><details><summary>All categories and subtypes</summary>${groups.map(g=>`<p><button data-group="${esc(g.name)}">${esc(modeTitle(g.name))}</button></p>${(g.mode.subtypes||[]).map(st=>`<p class="subtype"><button data-group="${esc(g.name)}" data-subtype="${esc(st.name)}">${esc(modeTitle(st.name))}</button>${(st.subtypes||[]).map(sub=>` → <button data-group="${esc(g.name)}" data-subtype="${esc(sub.name)}">${esc(modeTitle(sub.name))}</button>`).join('')}</p>`).join('')}`).join('')}</details>`;
 $('#tree-scope').value=treeScope;$('#tree-result').value=treeResult;
 $('#tree-scope').onchange=e=>{treeScope=e.target.value;renderTree();};$('#tree-result').onchange=e=>{treeResult=e.target.value;if(activeTreeMode)showNoteGroup(activeTreeMode,activeSubtype);};
 if(activeTreeMode)showNoteGroup(activeTreeMode,activeSubtype);else $('#explore-details').innerHTML='<p>Select a category to inspect its definition, subtype counts, and trace-level AI explanations.</p>';
}
function showNoteGroup(name,subtype=null){
 activeTreeMode=name;activeSubtype=subtype;const g=noteGroups().find(g=>g.name===name);if(!g)return;
 const reviewed=humanReviewed(), wanted={present:1,absent:0,uncertain:null};
 const labels=g.labels.filter(l=>(treeResult==='all'||l.label===wanted[treeResult])&&(!subtype||l.subtypes?.includes(subtype)));
 const origins=state.annotations.filter(n=>!n.deleted&&(g.mode.originating_annotations||[]).includes(n.id));
 $('#explore-details').innerHTML=`<h2>${esc(modeTitle(name))}${subtype?' · '+esc(modeTitle(subtype)):''}</h2><p>${esc(g.mode.definition)}</p><p><strong>Boundary:</strong> ${esc(g.mode.boundary)}</p>${g.mode.requirement_gap?`<details><summary>Specification clarification</summary><p>${esc(g.mode.requirement_gap)}</p></details>`:''}<div class="actions">${(g.mode.subtypes||[]).flatMap(st=>[st,...st.subtypes||[]]).map(st=>`<button data-group="${esc(name)}" data-subtype="${esc(st.name)}">${esc(modeTitle(st.name))} (${g.labels.filter(l=>l.subtypes?.includes(st.name)).length})</button>`).join('')}${subtype?`<button data-group="${esc(name)}">All subtypes</button>`:''}</div><details><summary>Originating human observations (${origins.length}) · not binary labels</summary>${origins.map(n=>`<article class="explore-note"><a href="/?trace=${encodeURIComponent(n.trace_id)}" target="_blank" rel="noopener">${esc(clusterData.points.find(p=>p.id===n.trace_id)?.scenario||n.trace_id)} ↗</a>${n.quote?`<blockquote>${esc(n.quote)}</blockquote>`:''}<p>${esc(n.note||n.text)}</p></article>`).join('')}</details><p>${labels.length} matching AI assessments. Model: ${esc(state.ai_assessments?.model||'unknown')}. Not human-confirmed.</p>${labels.map(l=>{const notes=state.annotations.filter(n=>!n.deleted&&n.trace_id===l.trace_id);return `<article class="explore-note"><a href="/?trace=${encodeURIComponent(l.trace_id)}" target="_blank" rel="noopener">${esc(l.scenario_id)} ↗</a> <span class="badge">${reviewed.has(l.trace_id)?'Has human observations':'Not manually reviewed'}</span>${assessmentCard(l)}${notes.length?`<details><summary>Original human observations (${notes.length})</summary>${notes.map(n=>`<p>${esc(n.note||n.text)}</p>`).join('')}</details>`:''}</article>`;}).join('')||'<p>No matching assessments.</p>'}`;
}
$('#show-clusters').onclick=()=>{exploreKind='clusters';renderExplore();};$('#show-tree').onclick=()=>{exploreKind='tree';renderExplore();};
document.addEventListener('click',e=>{const point=e.target.closest('[data-point]'),group=e.target.closest('[data-group]');if(point)showMapPoint(Number(point.dataset.point));if(group)showNoteGroup(group.dataset.group,group.dataset.subtype||null);});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-point]')){e.preventDefault();showMapPoint(Number(e.target.dataset.point));}});

loadState(true).catch(e=>notice(e.message));setInterval(()=>{if(!busy)loadState().catch(e=>notice('Connection interrupted. Browser drafts and previously saved notes are preserved.'))},5000);

if(new URLSearchParams(location.search).get('view')==='explore'){document.querySelector('[data-view=explore]').click();}
